                reveal(always(p.implies(tla_forall(a_to_q))).satisfied_by(ex));
                forall |i: nat| {
                    let ex_suf = ex.suffix(i);
                    reveal(p.implies(tla_forall(a_to_q)).satisfied_by(ex_suf));
                    if p.satisfied_by(ex_suf) {
                        // Now show `tla_forall(a_to_q).satisfied_by(ex_suf)`.
                        reveal(tla_forall(a_to_q).satisfied_by(ex_suf));
