                broadcast use super::$inductmod::lemma_obeys_cmp_spec;
                broadcast use group_laws_eq;
                lemma_obeys_cmp_obeys_traits::<$U>();
                $(lemma_obeys_cmp_obeys_traits::<$T>();)+
